import json
from httpbin.core import app

client = app.test_client()

def test_put_with_json_body_returns_200_and_all_keys():
    payload = {"key": "value", "number": 42}
    r = client.put(
        '/put',
        data=json.dumps(payload),
        content_type='application/json'
    )
    assert r.status_code == 200
    body = json.loads(r.data)
    expected_keys = {'url', 'args', 'headers', 'form', 'data', 'files', 'json', 'origin'}
    assert set(body.keys()) == expected_keys
    assert body['json'] == payload
    assert body['form'] == {}
    assert body['args'] == {}

test_put_with_json_body_returns_200_and_all_keys()
